param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/research-stopped-b.rws'))
# Read-only extraction of explicit original XML; no assembly or game execution.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function Numeric($parent,[string]$field){$n=$parent.SelectSingleNode($field);[ordered]@{value=if($n){[double]::Parse($n.InnerText,[Globalization.CultureInfo]::InvariantCulture)}else{0.0};present=($null -ne $n)}}
function Number($parent,[string]$field){(Numeric $parent $field).value}
function Stack($n){if($n.SelectSingleNode('stackCount')){[int]$n.stackCount}else{1}}
function Skill($n){[ordered]@{def=[string]$n.def;level=(Numeric $n 'level');xp_since_level=(Numeric $n 'xpSinceLastLevel');xp_since_midnight=(Numeric $n 'xpSinceMidnight');passion=if($n.SelectSingleNode('passion')){[string]$n.passion}else{'None'};passion_field_present=($null -ne $n.SelectSingleNode('passion'))}}
function Material($n){[ordered]@{id=[string]$n.id;def=[string]$n.def;count=(Stack $n);pos=[string]$n.pos;forbidden=([string]$n.forbidden -eq 'True');parent=$n.ParentNode.Name;container_owner=[string]$n.SelectSingleNode('ancestor::*[id and def][1]/id').InnerText}}
$map=$s.SelectSingleNode('//thing[id="Human958"]').ParentNode.ParentNode
$r=$s.SelectSingleNode('//researchManager');$keys=@($r.SelectNodes('progress/keys/li'));$values=@($r.SelectNodes('progress/values/li'))
if($keys.Count -ne $values.Count){throw 'Research progress keys/values length mismatch.'}
$progress=@(for($i=0;$i -lt $keys.Count;$i++){[ordered]@{def=$keys[$i].InnerText;progress=[double]::Parse($values[$i].InnerText,[Globalization.CultureInfo]::InvariantCulture)}})
$pawns=@($map.SelectNodes('./things/thing[def="Human"]')|ForEach-Object{
 $p=$_;$job=$p.SelectSingleNode('jobs/curJob');$driver=$p.SelectSingleNode('jobs/curDriver')
 [ordered]@{id=[string]$p.id;nick=[string]$p.name.nick;pos=[string]$p.pos;skills=@($p.SelectNodes('skills/skills/li')|ForEach-Object{Skill $_});last_xp_reset_tick=[int]$p.skills.lastXpSinceMidnightResetTimestamp;work_priority_values=@($p.SelectNodes('workSettings/priorities/vals/li')|ForEach-Object{[int]$_.InnerText});job=[ordered]@{def=[string]$job.def;load_id=[int]$job.loadID;target_a=[string]$job.targetA;target_b=[string]$job.targetB;start_tick=[int]$job.startTick;work_giver=[string]$job.workGiverDef;player_forced=([string]$job.playerForced -eq 'True');driver=[string]$driver.Class;driver_start_tick=[int]$driver.startTick;toil_index=[int]$driver.curToilIndex;ticks_left=[int]$driver.ticksLeftThisToil};carried=@($p.SelectNodes('carryTracker/innerContainer/innerList/li')|ForEach-Object{Material $_});hediffs=@($p.SelectNodes('healthTracker/hediffSet/hediffs/li')|ForEach-Object{[ordered]@{def=[string]$_.def;severity=(Numeric $_ 'severity');permanent=([string]$_.isPermanent -eq 'True')}});traits=@($p.SelectNodes('story/traits/allTraits/li')|ForEach-Object{[ordered]@{def=[string]$_.def;degree=(Numeric $_ 'degree')}})}
}|Sort-Object {$_.id})
$benches=@($map.SelectNodes('./things/thing[contains(def,"ResearchBench")]')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;class=[string]$_.Class;pos=[string]$_.pos;stuff=[string]$_.stuff;stuff_to_use=[string]$_.stuffToUse;health=(Numeric $_ 'health');spawned_tick=[int]$_.spawnedTick;work_done=(Numeric $_ 'workDone');resources=@($_.SelectNodes('resourceContainer/innerList/li')|ForEach-Object{Material $_})}}|Sort-Object {$_.id})
$materials=@($map.SelectNodes('.//*[id and (def="WoodLog" or def="Steel")]')|ForEach-Object{Material $_}|Sort-Object {$_.id})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;storyteller=[string]$s.SelectSingleNode('//storyteller/def').InnerText;difficulty=[string]$s.SelectSingleNode('//storyteller/difficulty').InnerText;player_faction=[string]$s.SelectSingleNode('//factionManager/allFactions/li[loadID="12"]/def').InnerText;research=[ordered]@{current_project=[string]$r.currentProj;current_project_field_present=($null -ne $r.SelectSingleNode('currentProj'));progress=$progress;techprints_xml=[string]$r.techprints.OuterXml;knowledge_xml=[string]$r.knowledge.OuterXml};pawns=$pawns;benches=$benches;materials=$materials;material_totals=[ordered]@{WoodLog=[int](($materials|Where-Object def -eq 'WoodLog'|Measure-Object count -Sum).Sum);Steel=[int](($materials|Where-Object def -eq 'Steel'|Measure-Object count -Sum).Sum)};scope='Read-only explicit XML. Current map selected through Human958; all three map Humans, research manager, research benches/blueprints/frames, and map WoodLog/Steel including frame and pawn containers. World-pawn material inventory excluded. Missing numeric skill fields mean zero with presence retained; omitted passion None. Work-priority vector retained without decoding; manual-priority checkbox is observed separately in UI. No source-game execution.'}|ConvertTo-Json -Depth 28
